"""Street Legends frontend: House tab in the shop + house images.
Run from repo root: python3 frontend/patch-houses-shop.py
Idempotent - safe to re-run.

WHAT IT DOES:
1. Writes the 3 house interior pictures to frontend/assets/houses/
   (apartment / cabin / mansion, from the pictures the user sent).
2. Adds house API calls to frontend/services/api.ts.
3. Adds a House tab to the Supply Shop (All / HP / EN / Combo / Stims
   / House) showing the 3 houses with pictures + prices + BUY.
   BUY shows an Are You Sure notice (with a replace warning if the
   player already owns a house) and places a house icon on the map
   where the player is standing.

FRONTEND change: needs a rebuild + new AAB upload to Play internal
testing. A backend Deploy alone does NOT ship this. Requires the
houses backend patch (patch-houses.py) to be applied + Deployed.
"""
import base64
import sys
from pathlib import Path

IMAGES = {
    "house-apartment.jpg": "",
    "house-cabin.jpg": "",
    "house-mansion.jpg": "",
}

API_ADDITIONS = '''
// ===== Player Houses =====
export const buyHouse = async (playerId: string, tier: string, latitude: number, longitude: number): Promise<any> => {
  const response = await api.post('/houses/buy', { player_id: playerId, tier, latitude, longitude });
  return response.data;
};

export const getPlayerHouse = async (playerId: string): Promise<any> => {
  const response = await api.get(`/houses/player/${playerId}`);
  return response.data.house;
};

export const getNearbyHouses = async (latitude: number, longitude: number, radius: number = 2000): Promise<any[]> => {
  const response = await api.get(`/houses/nearby?latitude=${latitude}&longitude=${longitude}&radius=${radius}`);
  return response.data;
};

export const toggleHouseHide = async (houseId: string, playerId: string): Promise<any> => {
  const response = await api.post(`/houses/${houseId}/toggle-hide`, { player_id: playerId });
  return response.data;
};

export const sellHouse = async (houseId: string, playerId: string): Promise<any> => {
  const response = await api.post(`/houses/${houseId}/sell`, { player_id: playerId });
  return response.data;
};
'''

HOUSES_CONST = '''
const HOUSES = [
  { tier: 'apartment', name: 'Street Apartment', price: 100000, image: require('../../assets/houses/house-apartment.jpg'), blurb: 'A rough city pad. Four walls, a barred window, and a door that locks.' },
  { tier: 'cabin', name: 'Country Cabin', price: 500000, image: require('../../assets/houses/house-cabin.jpg'), blurb: 'Wood walls, open fields, and quiet. Room to breathe.' },
  { tier: 'mansion', name: 'Luxury Mansion', price: 1000000, image: require('../../assets/houses/house-mansion.jpg'), blurb: 'Marble floors, a chandelier, and gardens. You made it.' },
];

const HOUSE_STYLES = StyleSheet.create({
  houseCard: { backgroundColor: '#111', borderRadius: 12, marginBottom: 12, overflow: 'hidden' },
  houseImage: { width: '100%', height: 180, resizeMode: 'cover' },
  houseInfo: { padding: 12 },
  houseName: { color: '#fff', fontSize: 18, fontWeight: '800' },
  houseBlurb: { color: '#999', fontSize: 13, marginTop: 4 },
  houseWarn: { color: '#f39c12', fontSize: 12, marginTop: 8, fontWeight: '700' },
  houseOwnedBadge: { backgroundColor: 'rgba(76,175,80,0.2)', borderRadius: 8, paddingVertical: 8, alignItems: 'center', marginTop: 10 },
  houseOwnedText: { color: '#4caf50', fontWeight: '800', fontSize: 13 },
  houseBuyBtn: { backgroundColor: '#f39c12', borderRadius: 8, paddingVertical: 10, alignItems: 'center', marginTop: 10 },
  houseBuyBtnDisabled: { backgroundColor: '#333' },
  houseBuyText: { color: '#fff', fontWeight: '800', fontSize: 14 },
  houseOwnedNote: { color: '#888', fontSize: 12, textAlign: 'center', marginTop: 4, marginBottom: 12 },
});
'''

SHOP_EDITS = [
    # FilterKey gains 'house'
    (
        "type FilterKey = 'all' | 'health_recharge' | 'energy_recharge' | 'combo' | 'consumable';",
        "type FilterKey = 'all' | 'health_recharge' | 'energy_recharge' | 'combo' | 'consumable' | 'house';",
        "FilterKey gains house",
    ),
    # Filters array gains House tab
    (
        "    { key: 'consumable', label: 'Stims', icon: 'fitness' },",
        "    { key: 'consumable', label: 'Stims', icon: 'fitness' },\n    { key: 'house', label: 'House', icon: 'home' },",
        "House tab added to filters",
    ),
    # API imports gain house calls
    (
        "import { getConsumableShop, buyConsumable, getPlayer } from '../../services/api';",
        "import { getConsumableShop, buyConsumable, getPlayer, buyHouse, getPlayerHouse } from '../../services/api';",
        "house API imports added",
    ),
    # State: myHouse + buyingHouse (after filter state)
    (
        "  const [filter, setFilter] = useState<FilterKey>('all');",
        "  const [filter, setFilter] = useState<FilterKey>('all');\n  const [myHouse, setMyHouse] = useState<any | null>(null);\n  const [buyingHouse, setBuyingHouse] = useState<string | null>(null);",
        "house state added",
    ),
    # Load owned house alongside shop data
    (
        "      setItems(data);\n      setActiveBuffs(buffs);",
        "      setItems(data);\n      setActiveBuffs(buffs);\n      if (playerId) {\n        try { const h = await getPlayerHouse(playerId); setMyHouse(h); } catch (_) {}\n      }",
        "owned house loaded with shop",
    ),
    # Buy handler (insert before filteredItems)
    (
        "  const filteredItems = filter === 'all' ? items : items.filter(i => i.category === filter);",
        """  const handleBuyHouse = (h: typeof HOUSES[0]) => {
    if (!playerId || !player) return;
    const pos = (player as any).position;
    if (!pos) { Alert.alert('No Location', 'We need your location to place the house.'); return; }
    if (player.cash < h.price) { Alert.alert('Not Enough Cash', `You need $${h.price.toLocaleString()} but only have $${player.cash.toLocaleString()}.`); return; }
    const warn = myHouse
      ? `You already own ${myHouse.name}. Buying ${h.name} will REPLACE it (the old house is gone). Are you sure?`
      : `Buy ${h.name} for $${h.price.toLocaleString()}? A house icon will be placed where you are standing right now.`;
    Alert.alert('Are You Sure?', warn, [
      { text: 'Cancel', style: 'cancel' },
      { text: 'Buy', onPress: async () => {
        try {
          setBuyingHouse(h.tier);
          const res = await buyHouse(playerId, h.tier, pos.latitude, pos.longitude);
          setMyHouse(res.house);
          const p = await getPlayer(playerId);
          setPlayer(p);
          Alert.alert('House Bought', `${h.name} is yours! Look for the \\u{1F3E0} icon on the map.`);
        } catch (e: any) {
          Alert.alert('Error', e.response?.data?.detail || 'Purchase failed');
        } finally { setBuyingHouse(null); }
      } },
    ]);
  };

  const filteredItems = filter === 'all' ? items : items.filter(i => i.category === filter);""",
        "house buy handler added",
    ),
    # Houses view when House tab selected (before Items List ScrollView)
    (
        "      {/* Items List */}\n      <ScrollView",
        """      {filter === 'house' ? (
        <ScrollView contentContainerStyle={styles.scrollContent}>
          {HOUSES.map((h) => {
            const owned = myHouse?.tier === h.tier;
            const canAfford = (player?.cash || 0) >= h.price;
            return (
              <View key={h.tier} style={HOUSE_STYLES.houseCard}>
                <Image source={h.image} style={HOUSE_STYLES.houseImage} />
                <View style={HOUSE_STYLES.houseInfo}>
                  <Text style={HOUSE_STYLES.houseName}>{h.name}</Text>
                  <Text style={HOUSE_STYLES.houseBlurb}>{h.blurb}</Text>
                  {myHouse && !owned && (
                    <Text style={HOUSE_STYLES.houseWarn}>You already own {myHouse.name} — buying replaces it.</Text>
                  )}
                  {owned ? (
                    <View style={HOUSE_STYLES.houseOwnedBadge}>
                      <Text style={HOUSE_STYLES.houseOwnedText}>YOUR HOUSE</Text>
                    </View>
                  ) : (
                    <TouchableOpacity
                      style={[HOUSE_STYLES.houseBuyBtn, !canAfford && HOUSE_STYLES.houseBuyBtnDisabled]}
                      disabled={!canAfford || buyingHouse === h.tier}
                      onPress={() => handleBuyHouse(h)}
                    >
                      {buyingHouse === h.tier ? (
                        <ActivityIndicator size="small" color="#fff" />
                      ) : (
                        <Text style={HOUSE_STYLES.houseBuyText}>BUY ${h.price.toLocaleString()}</Text>
                      )}
                    </TouchableOpacity>
                  )}
                </View>
              </View>
            );
          })}
          {myHouse && (
            <Text style={HOUSE_STYLES.houseOwnedNote}>You own: {myHouse.name} — tap its \\u{1F3E0} icon on the map to enter, hide, or sell.</Text>
          )}
        </ScrollView>
      ) : (
      <>
      {/* Items List */}
      <ScrollView""",
        "houses view added for House tab",
    ),
    # Close the House-tab ternary after the items ScrollView
    (
        "        )}\n      </ScrollView>\n\n      {/* Success Modal */}",
        "        )}\n      </ScrollView>\n      </>\n      )}\n\n      {/* Success Modal */}",
        "House-tab ternary closed",
    ),
]


def main():
    # 1. House images
    assets = Path("frontend/assets/houses")
    assets.mkdir(parents=True, exist_ok=True)
    for name, b64 in IMAGES.items():
        dest = assets / name
        if dest.exists() and dest.stat().st_size > 0:
            print(f"SKIP: {dest} already exists")
        else:
            dest.write_bytes(base64.b64decode(b64))
            print(f"OK: wrote {dest} ({dest.stat().st_size} bytes)")

    # 2. API additions
    api_path = Path("frontend/services/api.ts")
    if api_path.exists():
        src = api_path.read_text()
        if "buyHouse" not in src:
            if not src.endswith("\n"):
                src += "\n"
            src += API_ADDITIONS.lstrip("\n")
            api_path.write_text(src)
            print("OK: house API calls added to services/api.ts")
        else:
            print("SKIP: house API calls already in services/api.ts")
    else:
        print("WARNING: frontend/services/api.ts not found")

    # 3. Shop tab
    shop_path = Path("frontend/app/(tabs)/shop.tsx")
    if not shop_path.exists():
        print(f"ERROR: {shop_path} not found.")
        sys.exit(1)
    src = shop_path.read_text()
    if "HOUSES" not in src:
        # HOUSES const + styles go right after the FilterKey type line.
        anchor = "type FilterKey = 'all' | 'health_recharge' | 'energy_recharge' | 'combo' | 'consumable';"
        if anchor in src:
            src = src.replace(anchor, anchor + "\n" + HOUSES_CONST.lstrip("\n"), 1)
            print("OK: HOUSES const + styles added")
        else:
            print("WARNING: FilterKey anchor not found — HOUSES const skipped")
    for old, new, desc in SHOP_EDITS:
        if new.strip()[:60] in src or (old in src and new in src):
            # Already applied (or new text present) — skip quietly if new present.
            if new in src:
                print(f"SKIP: {desc} (already applied)")
                continue
        n = src.count(old)
        if n >= 1:
            src = src.replace(old, new, 1)
            print(f"OK: {desc}")
        else:
            print(f"WARNING: anchor not found — {desc}")
    shop_path.write_text(src)
    print("HOUSES_SHOP_OK")


if __name__ == "__main__":
    main()
